package com.oms.supplychain.service.wms;
import com.oms.common.api.RemoteInventoryService;
import com.oms.common.model.dto.wms.WmsInventoryBatchDto;
import com.oms.common.model.entity.wms.WmsInventoryBatch;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.net.*;
import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Return receipt -> immutable inventory lines -> idempotent posting. Platform status is never stock evidence. */
public abstract class WarehouseReturnService {
    protected enum Kind {
        EXCHANGE("wms_exchange_return","exchange_id","exchange_sn","THX","EXCHANGE_IN","EXCHANGE_RETURN_","RETURN_","换货"),
        REFUND("wms_refund_return","plan_id","refund_sn","THK","REFUND_IN","REFUND_RETURN_","REFUND_RETURN_","退款");
        final String table,ownerId,ownerSn,snPrefix,ticketType,inventoryPrefix,logPrefix,label;
        Kind(String t,String i,String s,String p,String type,String inv,String log,String label){table=t;ownerId=i;ownerSn=s;snPrefix=p;ticketType=type;inventoryPrefix=inv;logPrefix=log;this.label=label;}
    }
    private final Kind kind;
    protected WarehouseReturnService(Kind kind){this.kind=kind;}
    @Resource private WmsStore db;
    @Resource private WmsConnections connections;
    @Resource private WmsTenantRoutes routes;
    @Resource private WmsInteractionLog logs;
    @Resource private QimenReturnProtocol protocol;
    @Resource private RemoteInventoryService inventory;
    @SuppressWarnings("unchecked") private Map<String,Object> object(Object value){try{return value instanceof Map?(Map<String,Object>)value:db.json.readValue(String.valueOf(value),Map.class);}catch(Exception e){throw new IllegalArgumentException("退回快照无法读取");}}
    private Map<String,Object> latest(String company,long exchange){return db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? ORDER BY generation DESC LIMIT 1",company,exchange);}
    private Map<String,Object> task(String company,long task){return db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND id=?",company,task);}
    private Map<String,Object> summary(String company,long exchange){
        Map<String,Object> result=new LinkedHashMap<>(latest(company,exchange));result.remove("lease_token");result.remove("sender_json");result.remove("input_json");
        Map<String,Object> totals=db.one("SELECT COALESCE(SUM(accepted_quantity),0) accepted_quantity,COALESCE(SUM(posted_quantity),0) posted_quantity,MAX(IF(request_quantity>0,request_quantity,quantity)) quantity,COUNT(*) document_count FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=?",company,exchange);
        result.putAll(totals);long expected=id(totals.get("quantity")),accepted=id(totals.get("accepted_quantity")),posted=id(totals.get("posted_quantity"));
        long unfinished=db.jdbc.queryForObject("SELECT COUNT(*) FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? AND cancel_state<>'CONFIRMED' AND receipt_state<>'COMPLETED'",Long.class,company,exchange);
        result.put("receipt_state",posted==expected&&unfinished==0?"COMPLETED":accepted>posted?"POSTING":posted>0?"PARTIAL":"WAITING");
        result.put("pending_review_count",db.jdbc.queryForObject("SELECT COUNT(*) FROM "+kind.table+"_review r JOIN "+kind.table+" t ON t.company_code=r.company_code AND t.id=r.task_id WHERE r.company_code=? AND t."+kind.ownerId+"=? AND r.state='WAIT_REVIEW'",Long.class,company,exchange));
        if(kind==Kind.REFUND){long pending=db.jdbc.queryForObject("SELECT COUNT(DISTINCT e.id) FROM wms_refund_parcel_member m JOIN wms_refund_parcel_receipt e ON e.company_code=m.company_code AND e.parcel_id=m.parcel_id WHERE m.company_code=? AND m.plan_id=? AND e.state='WAIT_ALLOCATION' AND (JSON_SEARCH(e.payload,'one',CAST(m.id AS CHAR),NULL,'$.lines[*].lineNo') IS NOT NULL OR (?=1 AND JSON_SEARCH(e.payload,'one','',NULL,'$.lines[*].lineNo') IS NOT NULL))",Long.class,company,exchange,accepted<expected?1:0);result.put("parcel_pending_count",pending);result.put("pending_review_count",id(result.get("pending_review_count"))+pending);}
        return result;
    }
    public Map<String,Object> detail(String company,long exchange){
        Map<String,Object> result=summary(company,exchange);
        result.put("documents",db.jdbc.queryForList("SELECT id,return_sn,ticket_id,generation,store_code,real_store_code,owner_code,sku_sn,quantity,accepted_quantity,posted_quantity,attempts,dispatch_state,receipt_state,external_order,warehouse_status,cancel_state,cancel_mode,cancel_reason,cancel_actor,cancelled_quantity,cancelled_at,control_version,last_error,create_time,JSON_UNQUOTE(JSON_EXTRACT(input_json,'$.return_address')) return_address,JSON_UNQUOTE(JSON_EXTRACT(input_json,'$.return_contact')) return_contact FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? ORDER BY generation DESC LIMIT 100",company,exchange));
        result.put("lines",db.jdbc.queryForList("SELECT l.id,l.event_id,l.sku_sn,l.batch_code,l.good_qty,l.bad_qty,l.posted,t.return_sn,e.message_id,e.source_log_id,e.create_time FROM "+kind.table+"_line l JOIN "+kind.table+"_event e ON e.company_code=l.company_code AND e.id=l.event_id JOIN "+kind.table+" t ON t.company_code=l.company_code AND t.id=l.task_id WHERE t.company_code=? AND t."+kind.ownerId+"=? ORDER BY l.id DESC LIMIT 500",company,exchange));
        result.put("grades",db.one("SELECT COALESCE(SUM(l.good_qty),0) good_qty,COALESCE(SUM(l.bad_qty),0) bad_qty,COALESCE(SUM(IF(l.posted=1,l.good_qty+l.bad_qty,0)),0) posted_qty FROM "+kind.table+"_line l JOIN "+kind.table+" t ON t.company_code=l.company_code AND t.id=l.task_id WHERE t.company_code=? AND t."+kind.ownerId+"=?",company,exchange));
        result.put("rejected_receipts",db.jdbc.queryForList("SELECT l.id,l.result,l.error_info,l.create_time FROM wms_interaction_log l JOIN "+kind.table+" t ON t.company_code=l.company_code AND t.return_sn=l.ticket_sn WHERE t.company_code=? AND t."+kind.ownerId+"=? AND l.action='"+kind.logPrefix+"RECEIPT' AND l.result='FAILED' ORDER BY l.id DESC LIMIT 50",company,exchange));
        result.put("reviews",db.jdbc.queryForList("SELECT r.id,r.task_id,t.return_sn,r.message_id,r.quantity,r.state,r.reason,r.actor,r.create_time FROM "+kind.table+"_review r JOIN "+kind.table+" t ON t.company_code=r.company_code AND t.id=r.task_id WHERE r.company_code=? AND t."+kind.ownerId+"=? ORDER BY r.id DESC LIMIT 100",company,exchange));
        result.put("events",db.jdbc.queryForList("SELECT e.id,e.message_id,e.quantity,e.final_confirmation,e.state,e.last_error,e.create_time FROM "+kind.table+"_event e JOIN "+kind.table+" t ON t.company_code=e.company_code AND t.id=e.task_id WHERE t.company_code=? AND t."+kind.ownerId+"=? ORDER BY e.id DESC LIMIT 50",company,exchange));return result;
    }
    public Map<String,Object> prepare(String company,long exchange,Map<String,Object> input){routes.datasource(company);require(exchange>0,""+kind.label+"标识无效");String store=required(input,"store_code",64),sku=required(input,"sku_sn",128);long qty=id(input.get("quantity"));require(qty>0&&qty<=100000000,"退回数量无效");Map<String,Object> basis=object(input.get("return_basis"));String original=required(basis,"original_shipment_sn",64);BigDecimal cost=new BigDecimal(required(basis,"unit_cost",40));require(cost.signum()>=0,"原出库成本无效");String digest=QimenProtocol.hash("SHA-256",db.encode(new TreeMap<>(input)));
        db.tx().execute(s->{List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? ORDER BY generation FOR UPDATE",company,exchange);if(!old.isEmpty()){require(digest.equals(text(old.get(0).get("payload_hash"))),"已下发退回单快照不一致，请核对原单，不能覆盖重建");return null;}
            return createTask(company,exchange,input,1,qty);});
        post(company,exchange);Map<String,Object> t=latest(company,exchange);if("NONE".equals(t.get("cancel_state"))){if("PENDING".equals(t.get("dispatch_state")))send(company,id(t.get("id")),"CREATE");else if(Arrays.asList("UNKNOWN","SENDING").contains(text(t.get("dispatch_state"))))send(company,id(t.get("id")),"QUERY");}return summary(company,exchange);
    }
    protected Map<String,Object> stageNextSource(String c,long plan,Map<String,Object> input){Map<String,Object> old=latest(c,plan);require("CONFIRMED".equals(old.get("cancel_state"))&&id(old.get("accepted_quantity"))==id(old.get("posted_quantity")),"原来源未截停或存在待记账实收");Map<String,Object> total=summary(c,plan);require(id(input.get("quantity"))==id(total.get("quantity"))-id(total.get("accepted_quantity")),"重排数量必须等于来源剩余量");createTask(c,plan,input,Math.toIntExact(id(old.get("generation"))+1),id(total.get("quantity")),true);return latest(c,plan);}
    protected Map<String,Object> stageSource(String company,long plan,Map<String,Object> input){
        List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_refund_return WHERE company_code=? AND plan_id=? ORDER BY generation DESC LIMIT 1 FOR UPDATE",company,plan);
        if(old.isEmpty())createTask(company,plan,input,1,id(input.get("quantity")),true);
        else require(text(old.get(0).get("payload_hash")).equals(QimenProtocol.hash("SHA-256",db.encode(new TreeMap<>(input)))),"退回来源快照变化，请重新核对");
        return latest(company,plan);
    }
    private long createTask(String company,long exchange,Map<String,Object> input,int generation,long expected){return createTask(company,exchange,input,generation,expected,false);}
    private long createTask(String company,long exchange,Map<String,Object> input,int generation,long expected,boolean sourceOnly){
        String store=required(input,"store_code",64),sku=required(input,"sku_sn",128);long qty=id(input.get("quantity"));Map<String,Object> basis=object(input.get("return_basis"));String original=required(basis,"original_shipment_sn",64);BigDecimal cost=new BigDecimal(required(basis,"unit_cost",40));String digest=QimenProtocol.hash("SHA-256",db.encode(new TreeMap<>(input)));
            Map<String,Object> v=db.one("SELECT v.*,o.owner_code,o.is_enable,r.status relation_status,w.real_store_code,w.status warehouse_status FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.id=v.owner_warehouse_id AND UPPER(r.company_code)=UPPER(v.company_code) JOIN owner_info o ON o.id=r.owner_id AND UPPER(o.company_code)=UPPER(r.company_code) JOIN wms_real_store_info w ON w.id=r.real_store_id AND UPPER(w.company_code)=UPPER(r.company_code) WHERE UPPER(v.company_code)=? AND v.wms_simulation_code=?",company,store);if(kind==Kind.REFUND)require(!text(basis.get("owner_code")).isEmpty()&&text(basis.get("owner_code")).equals(text(v.get("owner_code"))),"退回接收货主必须与原发货来源一致");require(id(v.get("status"))==2&&id(v.get("is_enable"))==2&&id(v.get("relation_status"))==2&&id(v.get("warehouse_status"))==2,"退回虚拟仓、货主或实体仓已停用");require(v.get("connection_id")!=null&&!text(v.get("external_warehouse")).isEmpty()&&!text(v.get("external_owner")).isEmpty(),"请补全退回虚拟仓的仓库连接与外部编码");Map<String,Object> connection=connections.usable(company,id(v.get("connection_id")));require("QIMEN".equals(connection.get("provider"))&&"2.0".equals(connection.get("api_version")),"本期退回入库需要奇门2.0连接");
            long task=db.insert(kind.table,map("company_code",company,kind.ownerId,exchange,"generation",generation,"request_quantity",expected,"input_json",db.encode(input),"return_sn",(sourceOnly?"RSL":kind.snPrefix)+QimenProtocol.hash("SHA-256",company+"/"+exchange+(generation==1?"":"/"+generation)).substring(0,30),kind.ownerSn,required(input,kind.ownerSn,64),"order_sn",required(input,"order_sn",64),"platform_tid",required(input,"platform_tid",64),"original_shipment_sn",original,"store_code",store,"sku_sn",sku,"quantity",qty,"connection_id",v.get("connection_id"),"external_warehouse",v.get("external_warehouse"),"external_owner",v.get("external_owner"),"real_store_code",v.get("real_store_code"),"owner_code",v.get("owner_code"),"payload_hash",digest,"unit_cost",cost,"sender_json",db.encode(object(input.get("sender")))));String returnSn=(sourceOnly?"RSL":kind.snPrefix)+QimenProtocol.hash("SHA-256",company+"/"+exchange+(generation==1?"":"/"+generation)).substring(0,30);
            if(kind==Kind.REFUND)db.jdbc.update("UPDATE wms_refund_return SET refund_id=? WHERE company_code=? AND id=?",id(input.get("refund_id")),company,task);
            if(sourceOnly){db.jdbc.update("UPDATE wms_refund_parcel_member SET task_id=? WHERE company_code=? AND plan_id=? AND generation=? AND task_id IS NULL",task,company,exchange,generation);return task;}
            long ticket=db.insert("wms_tickets",map("company_code",company,"sn",returnSn,"business_type",kind.ticketType,"ticket_type",1,"original_sn",input.get(kind.ownerSn),"root_order_sn",input.get("order_sn"),kind==Kind.REFUND?"refund_id":"exchange_id",kind==Kind.REFUND?input.get("refund_id"):exchange,"relation_sn",returnSn,"wms_simulation_code",store,"wms_simulation_name",v.get("wms_simulation_name"),"real_store_code",v.get("real_store_code"),"actual_warehouse",1,"status_ticket",1,"user_name",""+kind.label+"处理","remark",""+kind.label+"退回，实际库存由专用回传记账"));
            db.insert("wms_tickets_goods",map("company_code",company,"sn",returnSn,"source_line_id",task,"inventory_type","ZP","sku_sn",sku,"goods_name",input.getOrDefault("goods_name",sku),"batch_code","","number_expected",qty,"number_actually",0,"number_dif_actually",qty,"purchase_price",cost,"inventory_is_handle",0));db.jdbc.update("UPDATE "+kind.table+" SET ticket_id=? WHERE company_code=? AND id=?",ticket,company,task);if(kind==Kind.REFUND)db.jdbc.update("UPDATE wms_refund_parcel_member SET task_id=? WHERE company_code=? AND plan_id=? AND generation=? AND task_id IS NULL",task,company,exchange,generation);return task;
    }
    public Map<String,Object> action(String company,long exchange,String action){return documentAction(company,exchange,id(latest(company,exchange).get("id")),action,Collections.emptyMap());}
    public Map<String,Object> documentAction(String company,long exchange,long document,String action,Map<String,Object> input){
        Map<String,Object> t=task(company,document);require(id(t.get(kind.ownerId))==exchange,"退回单不属于本"+kind.label+"单");
        if("retry".equals(action)){if(kind==Kind.REFUND)noPending(company,exchange);db.tx().execute(s->{Map<String,Object> current=db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND id=? FOR UPDATE",company,document);require("NONE".equals(current.get("cancel_state"))&&"FAILED".equals(current.get("dispatch_state")),"仅无截单的明确下发失败可重试；结果不明请查询原单");db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state='PENDING' WHERE company_code=? AND id=?",company,document);return null;});send(company,document,"CREATE");}
        else if("dispatch".equals(action)){if(kind==Kind.REFUND)noPending(company,exchange);send(company,document,"CREATE");}
        else if("query".equals(action))send(company,document,"QUERY");
        else if("cancel".equals(action))cancel(company,document,input);
        else if("rearrange".equals(action))rearrange(company,exchange,document,input);
        else if("review".equals(action)){review(company,exchange,document,input);long log=logs.start(company,id(t.get("connection_id")),document,text(t.get("return_sn")),"LOCAL",""+kind.logPrefix+"REVIEW",db.encode(input));logs.finish(log,"SUCCESS","已记录核对结论，原消息按幂等规则处理","",0);}
        else require("posting".equals(action),"退回操作无效");post(company,exchange);return detail(company,exchange);
    }
    private void send(String company,long document,String action){
        String lease=UUID.randomUUID().toString().replace("-","");
        if(db.jdbc.update("UPDATE "+kind.table+" SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,company,document)!=1)return;
        long log=0,start=System.currentTimeMillis();String response="",secret="";boolean contacted=false;
        try{
            Map<String,Object> t=task(company,document);t.put("business_type",kind.ticketType);t.put("business_sn",t.get(kind.ownerSn));
            if("CREATE".equals(action)){require("NONE".equals(t.get("cancel_state"))&&"PENDING".equals(t.get("dispatch_state")),"退回已有下发或截单，请查询原单");db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state='SENDING',attempts=attempts+1 WHERE company_code=? AND id=? AND lease_token=?",company,document,lease);}
            if("CANCEL".equals(action))require("PENDING".equals(t.get("cancel_state")),"没有待发送的截单意图");
            Map<String,Object> c="CREATE".equals(action)?connections.usable(company,id(t.get("connection_id"))):connections.get(company,id(t.get("connection_id")));
            if(kind==Kind.REFUND){List<Map<String,Object>> parcels=db.jdbc.queryForList("SELECT p.*,m.append_required,m.late_append FROM wms_refund_parcel_member m JOIN wms_refund_parcel p ON p.company_code=m.company_code AND p.id=m.parcel_id WHERE m.company_code=? AND m.task_id=?",company,document);if(!parcels.isEmpty()){Map<String,Object> p=parcels.get(0);require(id(p.get("connection_id"))==id(t.get("connection_id"))&&text(p.get("store_code")).equals(text(t.get("store_code"))),"退回包裹与仓库单据映射不一致");if("CREATE".equals(action)&&db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_member WHERE company_code=? AND parcel_id=?",Long.class,company,p.get("id"))>1)require(id(c.get("shared_return_waybill"))==1,"仓库未启用同运单多退回单能力，不能下发合包安排");if("CREATE".equals(action)&&id(p.get("append_required"))==1)require(id(c.get("shared_return_append"))==1,"仓库已关闭追加THK能力，不能下发新增安排");if("CREATE".equals(action)&&id(p.get("late_append"))==1)require(id(c.get("shared_return_late_append"))==1,"仓库未确认收货后补单能力，请先核对");t.put("parcel_sn",p.get("parcel_sn"));t.put("return_waybill",p.get("waybill"));t.put("return_carrier",p.get("carrier_code"));}}
            secret=connections.secret(c);WmsProtocol.Wire wire=protocol.request(c,secret,action,t);log=logs.start(company,id(c.get("id")),document,text(t.get("return_sn")),"OUT",""+kind.logPrefix+""+action,wire.body);
            require(db.jdbc.queryForObject("SELECT COUNT(*) FROM "+kind.table+" WHERE company_code=? AND id=? AND lease_token=? AND lease_until>DATE_ADD(NOW(),INTERVAL 30 SECOND)",Long.class,company,document,lease)==1,"仓库交互租约已失效");
            contacted=true;response=WmsHttp.post(wire);WmsProtocol.Reply r=protocol.reply(action,response);
            require(r.externalOrder.isEmpty()||text(t.get("external_order")).isEmpty()||text(t.get("external_order")).equals(r.externalOrder),"仓库退回单号与原受理不同");
            require(r.documentSn.isEmpty()||text(t.get("return_sn")).equals(r.documentSn),"仓库返回退回单身份不一致");require(r.owner.isEmpty()||text(t.get("external_owner")).equals(r.owner),"退回货主不一致");require(r.warehouse.isEmpty()||text(t.get("external_warehouse")).equals(r.warehouse),"退回仓库不一致");
            if("CANCEL".equals(action)){
                if(r.success)confirmCancel(company,document);else db.jdbc.update("UPDATE "+kind.table+" SET cancel_state='REJECTED',last_error=? WHERE company_code=? AND id=? AND lease_token=?","仓库拒绝取消："+r.code,company,document,lease);
            }else if(r.success){
                require(!r.externalOrder.isEmpty(),"仓库未返回退回单号，结果待核对");
                if("QUERY".equals(action))require(text(t.get("return_sn")).equals(r.documentSn)&&!r.warehouse.isEmpty()&&!r.owner.isEmpty(),"查询缺少原退回单、仓库或货主标识");
                db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state=IF(cancel_state='CONFIRMED','CANCELED','ACCEPTED'),external_order=?,warehouse_status=?,last_error='' WHERE company_code=? AND id=? AND lease_token=?",r.externalOrder,r.status,company,document,lease);
                if("CANCELED".equals(r.status)&&!"NONE".equals(t.get("cancel_state")))confirmCancel(company,document);
            }else{
                if("CREATE".equals(action))db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state=? WHERE company_code=? AND id=? AND lease_token=?",r.code.toUpperCase(Locale.ROOT).matches(".*(DUPLICATE|EXISTS).*")?"UNKNOWN":"FAILED",company,document,lease);
                db.jdbc.update("UPDATE "+kind.table+" SET last_error=? WHERE company_code=? AND id=? AND lease_token=?","仓库返回失败："+r.code,company,document,lease);
            }
            logs.finish(log,r.success?"SUCCESS":"FAILED",response.replace(secret,"***"),r.success?"":"仓库返回失败："+r.code,System.currentTimeMillis()-start);
            if(kind==Kind.REFUND&&r.success){Map<String,Object> current=task(company,document);logs.describe(log,"CANCEL".equals(action)?"本次截单已确认，截停时剩余 "+id(current.get("cancelled_quantity"))+" 件；已实收入账保留":"CREATE".equals(action)?"本次退回安排 "+id(current.get("quantity"))+" 件，仓库已接收；尚不代表实收或入账":"已查询仓库原单；查询不会新增实收或库存");}
        }catch(Exception failure){
            String error=contacted?"仓库操作结果待确认，请查询原单，勿重复提交":"退回连接或执行条件未就绪，请核对";
            if("CREATE".equals(action))db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state=? WHERE company_code=? AND id=? AND lease_token=? AND dispatch_state='SENDING'",contacted?"UNKNOWN":"FAILED",company,document,lease);
            if("CANCEL".equals(action))db.jdbc.update("UPDATE "+kind.table+" SET cancel_state=? WHERE company_code=? AND id=? AND lease_token=? AND cancel_state<>'CONFIRMED'",contacted?"UNKNOWN":"REJECTED",company,document,lease);
            db.jdbc.update("UPDATE "+kind.table+" SET last_error=? WHERE company_code=? AND id=? AND lease_token=?",error,company,document,lease);
            if(log==0)log=logs.start(company,id(task(company,document).get("connection_id")),document,text(task(company,document).get("return_sn")),"OUT",""+kind.logPrefix+""+action,"");
            logs.finish(log,"UNKNOWN",secret.isEmpty()?response:response.replace(secret,"***"),error,System.currentTimeMillis()-start);
        }finally{db.jdbc.update("UPDATE "+kind.table+" SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",company,document,lease);}
    }
    private List<Map<String,Object>> lockDocuments(String company,long exchange){return db.jdbc.queryForList("SELECT * FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? ORDER BY generation FOR UPDATE",company,exchange);}
    private void idle(Map<String,Object> t){require(t.get("lease_until")==null||!((java.sql.Timestamp)t.get("lease_until")).toLocalDateTime().isAfter(java.time.LocalDateTime.now()),"单据正在交互或记账，请稍后核对");}
    private void noPending(String company,long exchange){require(id(summary(company,exchange).get("pending_review_count"))==0,"存在待人工核对的退回回传，请先处理");}
    private void confirmCancel(String company,long document){db.tx().execute(s->{Map<String,Object> t=db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND id=? FOR UPDATE",company,document);require(id(t.get("accepted_quantity"))==id(t.get("posted_quantity")),"已有实收待记账，保留截单待核对");
        db.jdbc.update("UPDATE "+kind.table+" SET cancel_state='CONFIRMED',dispatch_state='CANCELED',cancelled_quantity=quantity-accepted_quantity,cancelled_at=COALESCE(cancelled_at,NOW()),control_version=control_version+1,last_error='' WHERE company_code=? AND id=? AND cancel_state<>'CONFIRMED'",company,document);
        if(t.get("ticket_id")!=null)db.jdbc.update("UPDATE wms_tickets SET cutoff_state='COMPLETED',cancelled_quantity=?,status_ticket=?,remark='"+kind.label+"退回剩余已截停，实收入账保留' WHERE company_code=? AND id=?",Math.max(0,id(t.get("quantity"))-id(t.get("accepted_quantity"))),id(t.get("accepted_quantity"))>0?2:5,company,t.get("ticket_id"));return null;});}
    private void cancel(String company,long document,Map<String,Object> input){
        Map<String,Object> prior=task(company,document);
        String action=db.tx().execute(s->{lockDocuments(company,id(prior.get(kind.ownerId)));Map<String,Object> t=task(company,document);idle(t);
            if("CONFIRMED".equals(t.get("cancel_state")))return "NONE";
            require(id(t.get("control_version"))==id(input.get("document_version")),"退回单已变化，请刷新");
            String mode=required(input,"mode",24),reason=required(input,"reason",500);require(Arrays.asList("WITHDRAW","TERMINATE").contains(mode),"请选择撤回安排或终止剩余退回");boolean localUnsent="PENDING".equals(text(t.get("dispatch_state")))&&id(t.get("attempts"))==0&&text(t.get("external_order")).isEmpty()&&id(t.get("accepted_quantity"))==0&&id(t.get("posted_quantity"))==0&&db.jdbc.queryForObject("SELECT COUNT(*) FROM "+kind.table+"_event WHERE company_code=? AND task_id=?",Long.class,company,document)==0;
            // A pending late receipt must not prevent stopping its replacement document.
            // Acceptance still requires every arrangement to be stopped or completed.
            if(!localUnsent&&kind!=Kind.REFUND)noPending(company,id(t.get(kind.ownerId)));
            require(id(t.get("accepted_quantity"))==id(t.get("posted_quantity")),"存在实收待记账，请先核对原回执");require(id(t.get("accepted_quantity"))<id(t.get("quantity")),"已全部实收，不能撤销入库事实");
            if(Arrays.asList("PENDING","UNKNOWN").contains(text(t.get("cancel_state"))))return "QUERY";
            if(Arrays.asList("UNKNOWN","SENDING").contains(text(t.get("dispatch_state"))))return "QUERY";
            db.jdbc.update("UPDATE "+kind.table+" SET cancel_state='PENDING',cancel_mode=?,cancel_reason=?,cancel_actor=?,control_version=control_version+1 WHERE company_code=? AND id=?",mode,reason,required(input,"actor",64),company,document);
            if(id(t.get("attempts"))==0&&Arrays.asList("PENDING","FAILED").contains(text(t.get("dispatch_state")))){confirmCancel(company,document);return "LOCAL";}
            require("ACCEPTED".equals(t.get("dispatch_state")),"仓库受理结果待核对");return "CANCEL";
        });
        if("LOCAL".equals(action)){Map<String,Object> t=task(company,document);long log=logs.start(company,id(t.get("connection_id")),document,text(t.get("return_sn")),"LOCAL",""+kind.logPrefix+"CANCEL",db.encode(map("reason",input.get("reason"),"mode",input.get("mode"),"actor",input.get("actor"))));logs.finish(log,"SUCCESS","本地撤回，未向仓库发送创建请求","",0);if(kind==Kind.REFUND)logs.describe(log,"本次安排已本地停止，未向仓库下发；不改变库存");}
        else if(!"NONE".equals(action))send(company,document,action);
    }
    private void rearrange(String company,long exchange,long document,Map<String,Object> input){
        db.tx().execute(s->{List<Map<String,Object>> all=lockDocuments(company,exchange);Map<String,Object> last=all.get(all.size()-1);require(id(last.get("id"))==document&&id(last.get("control_version"))==id(input.get("document_version")),"请从最新退回单重新安排，或刷新版本");noPending(company,exchange);
            for(Map<String,Object> t:all){idle(t);require("CONFIRMED".equals(t.get("cancel_state"))||"COMPLETED".equals(t.get("receipt_state")),"原退回安排尚未确认结束，不能重复生成");require(id(t.get("accepted_quantity"))==id(t.get("posted_quantity")),"原回执尚未完成记账");}
            Map<String,Object> totals=summary(company,exchange);long remaining=id(totals.get("quantity"))-id(totals.get("accepted_quantity"));require(remaining>0&&remaining==id(input.get("quantity"))&&all.size()<100,"请仅重新安排尚未实收的全部剩余数量");
            Map<String,Object> command=new LinkedHashMap<>(object(all.get(0).get("input_json")));command.put("quantity",remaining);command.put("store_code",required(input,"store_code",64));command.put("return_address",required(input,"return_address",500));command.put("return_contact",required(input,"return_contact",200));
            createTask(company,exchange,command,Math.toIntExact(id(last.get("generation"))+1),id(totals.get("quantity")));return null;});
    }
    private void review(String company,long exchange,long document,Map<String,Object> input){
        db.tx().execute(s->{List<Map<String,Object>> docs=lockDocuments(company,exchange);Map<String,Object> t=task(company,document);Map<String,Object> review=db.one("SELECT * FROM "+kind.table+"_review WHERE company_code=? AND task_id=? AND id=? FOR UPDATE",company,document,id(input.get("review_id")));
            require("WAIT_REVIEW".equals(review.get("state")),"该回传已经核对，请刷新");String reason=required(input,"reason",500),actor=required(input,"actor",64),decision=required(input,"decision",24);require(Arrays.asList("ACCEPT","REJECT").contains(decision),"核对动作无效");require(!text(input.get("evidence")).isEmpty()&&reason.length()+text(input.get("evidence")).length()<=480,"请填写核对凭证；处理依据与凭证合计最多480字");
            if("ACCEPT".equals(decision)){for(Map<String,Object> d:docs){idle(d);require("CONFIRMED".equals(d.get("cancel_state"))||"COMPLETED".equals(d.get("receipt_state")),"请先截停其他退回安排，避免迟到实收与新单重复收货");}
                WmsProtocol.Receipt receipt;try{receipt=db.json.readValue(text(review.get("payload")),WmsProtocol.Receipt.class);}catch(Exception failure){throw new IllegalArgumentException("原回传快照无法读取");}
                acceptLocked(company,t,receipt,id(review.get("source_log_id")),true);
            }
            db.jdbc.update("UPDATE "+kind.table+"_review SET state=?,reason=?,actor=? WHERE company_code=? AND id=?","ACCEPT".equals(decision)?"ACCEPTED":"REJECTED",reason+"；凭证："+required(input,"evidence",500),actor,company,review.get("id"));return null;});
    }
    public String callback(String company,String callbackKey,Map<String,String> params,String body){Map<String,Object> c=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",company,callbackKey);long log=logs.start(company,id(c.get("id")),null,"","IN",""+kind.logPrefix+"RECEIPT",body),start=System.currentTimeMillis();QimenProtocol ack=new QimenProtocol();try{WmsProtocol.Receipt receipt=protocol.callback(c,connections.secret(c),params,body);Map<String,Object> t=db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND connection_id=? AND return_sn=?",company,c.get("id"),receipt.ticketSn);db.jdbc.update("UPDATE wms_interaction_log SET task_id=?,ticket_sn=? WHERE id=?",t.get("id"),receipt.ticketSn,log);accept(company,t,receipt,log);if(kind==Kind.REFUND)db.jdbc.update("UPDATE wms_refund_return SET progress_revision=progress_revision+1,notify_pending=1 WHERE company_code=? AND id=?",company,t.get("id"));postTask(company,id(t.get("id")));if(kind==Kind.REFUND){long waiting=db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_return_review WHERE company_code=? AND task_id=? AND message_id=? AND state='WAIT_REVIEW'",Long.class,company,t.get("id"),receipt.messageId);logs.describe(log,waiting>0?"本次回传已接收并转人工核对；待核对部分未入账":"本次回传已接收，按原消息幂等记账；重复通知不重复增加库存");}String reply=ack.acknowledgement(true,"退回实收已接收，库存记账与验收分别处理");logs.finish(log,"SUCCESS",reply,"",System.currentTimeMillis()-start);return reply;}catch(Exception e){String message=e instanceof IllegalArgumentException?text(e.getMessage()):"退回接收未完成，请重试";String reply=ack.acknowledgement(false,message);logs.finish(log,"FAILED",reply,message,System.currentTimeMillis()-start);return reply;}}
    void accept(String company,Map<String,Object> task,WmsProtocol.Receipt r,long log){db.tx().execute(s->{lockDocuments(company,id(task.get(kind.ownerId)));acceptLocked(company,task(company,id(task.get("id"))),r,log,false);return null;});}
    protected void acceptLocked(String company,Map<String,Object> t,WmsProtocol.Receipt r,long log,boolean reviewed){
        require(r.messageId!=null&&r.messageId.length()>=1&&r.messageId.length()<=128,"退回消息 ID 缺失或过长");require(r.externalOrder!=null&&!r.externalOrder.isEmpty()&&r.warehouse!=null&&r.owner!=null,"退回身份不完整");
        require(text(t.get("return_sn")).equals(r.ticketSn)&&text(t.get("external_warehouse")).equals(r.warehouse)&&text(t.get("external_owner")).equals(r.owner),"退回单、仓库或货主不属于原任务");require(text(t.get("external_order")).isEmpty()||text(t.get("external_order")).equals(r.externalOrder),"退回仓库单号与原受理不同");
        String payload=db.encode(r),digest=QimenProtocol.hash("SHA-256",payload);List<Map<String,Object>> old=db.jdbc.queryForList("SELECT payload_hash FROM "+kind.table+"_event WHERE company_code=? AND task_id=? AND message_id=?",company,t.get("id"),r.messageId);
        if(!old.isEmpty()){require(digest.equals(text(old.get(0).get("payload_hash"))),"同一消息内容不同，请人工核对；本次不记账");return;}
        long total=0;for(WmsProtocol.Line l:r.lines){if(kind==Kind.REFUND&&!reviewed&&!text(t.get("sku_sn")).equals(l.sku)){pendingReview(company,t,r,log,"退回商品与原发货来源不符；本次未入账");return;}require(text(t.get("sku_sn")).equals(l.sku)&&(l.owner==null||l.owner.isEmpty()||r.owner.equals(l.owner)),"退回商品或货主与审核申请不符；本次不记账");require(l.good>=0&&l.bad>=0&&text(l.batch).length()<=100,"退回批次或数量无效");total=Math.addExact(total,(long)l.good+l.bad);}
        if(!reviewed){List<Map<String,Object>> reviews=db.jdbc.queryForList("SELECT payload_hash FROM "+kind.table+"_review WHERE company_code=? AND task_id=? AND message_id=?",company,t.get("id"),r.messageId);if(!reviews.isEmpty()){require(reviews.stream().anyMatch(v->digest.equals(text(v.get("payload_hash")))),"同一核对消息内容不同，请人工核对");return;}
            if("CONFIRMED".equals(t.get("cancel_state"))){db.insert(""+kind.table+"_review",map("company_code",company,"task_id",t.get("id"),"message_id",r.messageId,"payload_hash",digest,"payload",payload,"quantity",total,"source_log_id",log,"reason","截单确认后收到实收，待人工核对；本次未入账"));return;}
        }
        if(kind==Kind.REFUND&&!reviewed&&(id(t.get("accepted_quantity"))+total>id(t.get("quantity"))||r.complete&&id(t.get("accepted_quantity"))+total!=id(t.get("quantity")))){pendingReview(company,t,r,log,"最终数量不足或超过单据范围；请核对原回传，本次未入账");return;}require(!"COMPLETED".equals(t.get("receipt_state")),"退回已完成，新增消息请人工核对");require((total>0||r.complete)&&id(t.get("accepted_quantity"))+total<=id(t.get("quantity")),"退回数量超出单据或没有实收，请人工核对；本次不记账");
        Map<String,Object> aggregate=summary(company,id(t.get(kind.ownerId)));require(id(aggregate.get("accepted_quantity"))+total<=id(aggregate.get("quantity")),"累计实收超过"+kind.label+"申请，不能入账");
        if(r.complete&&!reviewed)require(id(t.get("accepted_quantity"))+total==id(t.get("quantity")),"最终退回数量不足单据，请人工核对；本次不记账");
        long event=db.insert(""+kind.table+"_event",map("company_code",company,"task_id",t.get("id"),"message_id",r.messageId,"payload_hash",digest,"payload",payload,"quantity",total,"final_confirmation",r.complete?1:0,"source_log_id",log));int index=0;
        for(WmsProtocol.Line l:r.lines)if(l.good+l.bad>0)db.insert(""+kind.table+"_line",map("company_code",company,"task_id",t.get("id"),"event_id",event,"line_no",++index,"sku_sn",l.sku,"batch_code",text(l.batch).isEmpty()?""+kind.snPrefix+"_"+""+t.get("id"):l.batch,"good_qty",l.good,"bad_qty",l.bad));
        db.jdbc.update("UPDATE "+kind.table+" SET dispatch_state=IF(cancel_state='CONFIRMED','CANCELED','ACCEPTED'),external_order=?,warehouse_status=?,accepted_quantity=accepted_quantity+?,receipt_state=?,control_version=control_version+1,last_error='' WHERE company_code=? AND id=?",r.externalOrder,r.status,total,r.complete?"POSTING_FINAL":"POSTING",company,t.get("id"));
    }
    private void pendingReview(String company,Map<String,Object> t,WmsProtocol.Receipt r,long log,String reason){long total=0;for(WmsProtocol.Line l:r.lines)total=Math.addExact(total,(long)l.good+l.bad);String payload=db.encode(r);db.jdbc.update("INSERT IGNORE INTO "+kind.table+"_review(company_code,task_id,message_id,payload_hash,payload,quantity,source_log_id,reason) VALUES (?,?,?,?,?,?,?,?)",company,t.get("id"),r.messageId,QimenProtocol.hash("SHA-256",payload),payload,total,log,reason);}
    protected void post(String company,long exchange){for(Long document:db.jdbc.queryForList("SELECT id FROM "+kind.table+" WHERE company_code=? AND "+kind.ownerId+"=? ORDER BY id LIMIT 100",Long.class,company,exchange))postTask(company,document);}
    private void postTask(String company,long document){String lease=UUID.randomUUID().toString().replace("-","");if(db.jdbc.update("UPDATE "+kind.table+" SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,company,document)!=1)return;try{Map<String,Object> t=db.one("SELECT * FROM "+kind.table+" WHERE company_code=? AND id=?",company,document);for(Map<String,Object> line:db.jdbc.queryForList("SELECT * FROM "+kind.table+"_line WHERE company_code=? AND task_id=? AND posted=0 ORDER BY id LIMIT 100",company,t.get("id"))){require(db.jdbc.update("UPDATE "+kind.table+" SET lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW()",company,document,lease)==1,"退回记账租约已失效");WmsInventoryBatch batch=new WmsInventoryBatch();batch.setCompanyCode(company);batch.setStoreCode(text(t.get("store_code")));batch.setSkuSn(text(line.get("sku_sn")));batch.setBatchCode(text(line.get("batch_code")));batch.setZpActualNumber(Math.toIntExact(id(line.get("good_qty"))));batch.setZpAvailableNumber(Math.toIntExact(id(line.get("good_qty"))));batch.setCpActualNumber(Math.toIntExact(id(line.get("bad_qty"))));batch.setCpAvailableNumber(Math.toIntExact(id(line.get("bad_qty"))));batch.setTransactionPrice(new BigDecimal(text(t.get("unit_cost"))));WmsInventoryBatchDto dto=new WmsInventoryBatchDto();dto.setRelationSn(""+kind.inventoryPrefix+""+line.get("id"));dto.setWmsInventoryBatch(batch);R<Boolean> reply=inventory.addInventory(dto,company);require(reply!=null&&R.isSuccess(reply)&&Boolean.TRUE.equals(reply.getData()),"退回库存记账未完成，原记录保留");db.jdbc.update("UPDATE "+kind.table+"_line SET posted=1 WHERE company_code=? AND id=?",company,line.get("id"));}
            db.tx().execute(s->{db.jdbc.update("UPDATE "+kind.table+"_event e SET state='POSTED',last_error='' WHERE company_code=? AND task_id=? AND NOT EXISTS(SELECT 1 FROM "+kind.table+"_line l WHERE l.company_code=e.company_code AND l.event_id=e.id AND l.posted=0)",company,t.get("id"));long quantity=db.jdbc.queryForObject("SELECT COALESCE(SUM(good_qty+bad_qty),0) FROM "+kind.table+"_line WHERE company_code=? AND task_id=? AND posted=1",Long.class,company,t.get("id"));boolean full=quantity==id(t.get("quantity"))&&db.jdbc.queryForObject("SELECT COUNT(*) FROM "+kind.table+"_event WHERE company_code=? AND task_id=? AND final_confirmation=1 AND state='POSTED'",Long.class,company,t.get("id"))>0;db.jdbc.update("UPDATE "+kind.table+" SET posted_quantity=?,receipt_state=?,last_error=IF(cancel_state='NONE','',last_error) WHERE company_code=? AND id=?",quantity,full?"COMPLETED":quantity>0?"PARTIAL":"WAITING",company,t.get("id"));if(t.get("ticket_id")!=null){Map<String,Object> grades=db.one("SELECT COALESCE(SUM(good_qty),0) good_qty,COALESCE(SUM(bad_qty),0) bad_qty FROM "+kind.table+"_line WHERE company_code=? AND task_id=? AND posted=1",company,t.get("id"));db.jdbc.update("UPDATE wms_tickets_goods SET number_actually=?,number_zp=?,number_cp=?,number_dif_actually=number_expected-?,inventory_is_handle=? WHERE UPPER(company_code)=? AND sn=?",quantity,grades.get("good_qty"),grades.get("bad_qty"),quantity,quantity>0?2:0,company,t.get("return_sn"));if("CONFIRMED".equals(t.get("cancel_state"))){db.jdbc.update("UPDATE wms_tickets_goods SET cancelled_quantity=GREATEST(number_expected-number_actually,0) WHERE UPPER(company_code)=? AND sn=?",company,t.get("return_sn"));db.jdbc.update("UPDATE wms_tickets SET cutoff_state='COMPLETED',cancelled_quantity=GREATEST(?-?,0) WHERE company_code=? AND id=?",t.get("quantity"),quantity,company,t.get("ticket_id"));}db.jdbc.update("UPDATE wms_tickets SET status_ticket=?,inventory_status=?,status_notify=1 WHERE UPPER(company_code)=? AND id=?","CONFIRMED".equals(t.get("cancel_state"))?(quantity>0?2:5):full?2:1,quantity>0?2:0,company,t.get("ticket_id"));}return null;});
        }catch(RuntimeException e){db.jdbc.update("UPDATE "+kind.table+" SET last_error='退回库存记账未完成，请核对原回执' WHERE company_code=? AND id=?",company,document);}finally{db.jdbc.update("UPDATE "+kind.table+" SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",company,document,lease);}}
}
